import XCTest

@testable import TractandaCore

final class PeerTimestampAuthorityTests: XCTestCase {
    private let effectiveAt = "2026-10-15T12:00:00.0000000Z"
    // Fixed RFC UUIDv1 fixtures differ by exactly one 100 ns tick around effectiveAt.
    // Their timestamp and node bits are explicit test data, not generated by production helpers.
    private let before = "f286dfff-c88f-11f1-8000-001122334455"
    private let equal = "f286e000-c88f-11f1-8000-001122334455"
    private let after = "f286e001-c88f-11f1-8000-001122334455"

    func testTimestampProfileAndExact100NanosecondBoundary() throws {
        XCTAssertEqual(PeerLifecycle.timestampProfile, "tractanda.peer-retirement-time.v1")
        XCTAssertEqual(
            try XCTUnwrap(UUID(uuidString: before)?.version1Components).timestampUTC,
            "2026-10-15T11:59:59.9999999Z")
        XCTAssertEqual(
            try XCTUnwrap(UUID(uuidString: equal)?.version1Components).timestampUTC,
            "2026-10-15T12:00:00.0000000Z")
        XCTAssertEqual(
            try XCTUnwrap(UUID(uuidString: after)?.version1Components).timestampUTC,
            "2026-10-15T12:00:00.0000001Z")
        XCTAssertFalse(try PeerLifecycle.revisionIsRemoved(revisionID: before, effectiveAt: effectiveAt))
        XCTAssertTrue(try PeerLifecycle.revisionIsRemoved(revisionID: equal, effectiveAt: effectiveAt))
        XCTAssertTrue(try PeerLifecycle.revisionIsRemoved(revisionID: after, effectiveAt: effectiveAt))
    }

    func testTimestampComparisonIgnoresUUIDNodeAndClockSequence() throws {
        // Same fixed timestamp as equality fixture, with a distinct sequence and node.
        XCTAssertTrue(
            try PeerLifecycle.revisionIsRemoved(
                revisionID: "f286e000-c88f-11f1-bfff-fedcba987654", effectiveAt: effectiveAt))
    }

    func testTimestampRejectsNonV1OrNonCanonicalRevisionIDs() {
        for id in ["06082000-e662-23a3-8000-001122334455", "06082000-e662-13a3-8000-00112233445z"] {
            XCTAssertThrowsError(
                try PeerLifecycle.revisionIsRemoved(revisionID: id, effectiveAt: effectiveAt))
        }
    }

    func testTimestampRejectsInvalidEffectiveAt() {
        for value in ["2026-02-30T12:00:00.0000000Z", "not-a-time"] {
            XCTAssertThrowsError(try PeerLifecycle.revisionIsRemoved(revisionID: equal, effectiveAt: value))
        }
    }

    func testSourceAdministrationRoundTripsCanonicalFields() throws {
        let source = try SourceAdministration(
            defaultAdministratorGroup: "admin", serviceOwnerPrincipal: "tractanda")
        XCTAssertEqual(try SourceAdministration(source.itemValue), source)
        XCTAssertEqual(
            try XCTUnwrap(source.itemValue.map?.keys.sorted()),
            ["defaultAdministratorGroup", "serviceOwnerPrincipal"])
        XCTAssertThrowsError(try SourceAdministration(.object(["defaultAdministratorGroup": .text("admin")])))
    }

    func testSourceDefaultAdministratorGroupIsIndependentOfReceiverDefaults() throws {
        let source = try SourceAdministration(
            defaultAdministratorGroup: "sudo", serviceOwnerPrincipal: "owner")
        let configuration = try AccessConfiguration(
            .object([
                "profile": .text(AccessConfiguration.profile), "administration": .text("system"),
            ]))
        // The same source testimony yields the same result on macOS and Linux receivers.
        XCTAssertTrue(
            source.isAdministrator(
                configuration: configuration, principal: "alice", sourceUID: 501, groups: ["sudo"]))
        XCTAssertFalse(
            source.isAdministrator(
                configuration: configuration, principal: "alice", sourceUID: 501, groups: ["admin"]))
    }

    func testExplicitAdministratorGroupOverridesSourceDefault() throws {
        let source = try SourceAdministration(
            defaultAdministratorGroup: "sudo", serviceOwnerPrincipal: "owner")
        let configuration = try AccessConfiguration(
            .object([
                "profile": .text(AccessConfiguration.profile), "administration": .text("system"),
                "administratorGroup": .text("wheel"),
            ]))
        XCTAssertTrue(
            source.isAdministrator(
                configuration: configuration, principal: "alice", sourceUID: 501, groups: ["wheel"]))
        XCTAssertFalse(
            source.isAdministrator(
                configuration: configuration, principal: "alice", sourceUID: 501, groups: ["sudo", "admin"]))
    }

    func testServiceOwnerRequiresAttestedPrincipalRatherThanUIDOrRights() throws {
        let source = try SourceAdministration(
            defaultAdministratorGroup: "admin", serviceOwnerPrincipal: "service-owner")
        let configuration = try AccessConfiguration(
            .object([
                "profile": .text(AccessConfiguration.profile), "administration": .text("serviceOwner"),
            ]))
        XCTAssertTrue(
            source.isAdministrator(
                configuration: configuration, principal: "service-owner", sourceUID: 501, groups: []))
        XCTAssertFalse(
            source.isAdministrator(
                configuration: configuration, principal: "admin", sourceUID: 0, groups: ["admin"]))
    }

    func testSourceUIDZeroIsEvaluatedOnlyBySourceSemantics() throws {
        let source = try SourceAdministration(
            defaultAdministratorGroup: "admin", serviceOwnerPrincipal: "owner")
        let configuration = try AccessConfiguration(
            .object([
                "profile": .text(AccessConfiguration.profile), "administration": .text("system"),
            ]))
        XCTAssertTrue(
            source.isAdministrator(
                configuration: configuration, principal: "source-root", sourceUID: 0, groups: []))
        XCTAssertFalse(
            source.isAdministrator(
                configuration: configuration, principal: "receiver-root", sourceUID: 501, groups: []))
    }
}
